import csv

with open('contacts.csv', newline='', encoding='utf-8') as f:
    rows = list(csv.DictReader(f))

best = {}
for r in rows:
    email = r['email'].strip().lower()
    created = r['created'].strip()
    rec = {'name': r['name'], 'email': email, 'created': created}
    if email not in best:
        best[email] = rec
    elif created < best[email]['created']:
        best[email] = rec

out = sorted(best.values(), key=lambda x: (x['created'], x['email']))

with open('clean.csv', 'w', newline='', encoding='utf-8') as f:
    w = csv.writer(f, lineterminator='\n')
    w.writerow(['name', 'email', 'created'])
    for x in out:
        w.writerow([x['name'], x['email'], x['created']])
